CREATE TABLE cap19_stock (product_id INTEGER PRIMARY KEY, stock_qty INTEGER NOT NULL CHECK (stock_qty >= 0));
CREATE TABLE cap19_sales (sale_id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK (quantity > 0));
INSERT INTO cap19_stock VALUES (1, 10), (2, 5);
BEGIN;
INSERT INTO cap19_sales VALUES (1, 1, 3);
UPDATE cap19_stock SET stock_qty = stock_qty - 3 WHERE product_id = 1 AND stock_qty >= 3;
COMMIT;
SELECT s.sale_id, s.quantity, st.stock_qty FROM cap19_sales AS s JOIN cap19_stock AS st ON st.product_id = s.product_id;

